77:   function readProgress() {
78:     try {
79:       const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
80:       return {
81:         streak: safeCount(value.streak), hits: safeCount(value.hits),
82:         best: safeCount(value.best),
83:       };
84:     } catch (_) {
85:       return { streak: 0, hits: 0, best: 0 };
86:     }
87:   }
88: 
89:   function safeCount(value) {
90:     return Number.isSafeInteger(value) && value >= 0 ? Math.min(value, 999999) : 0;
91:   }
92: 
93:   function saveProgress() {
94:     try {
95:       localStorage.setItem(STORAGE_KEY, JSON.stringify({
96:         streak: state.streak, hits: state.hits, best: state.best,
97:       }));
98:     } catch (_) {
99:       // Private browsing or a full storage quota must not interrupt practice.
100:     }
101:   }
102: 
103:   function handleTap() {
104:     const now = performance.now();
105:     pulseTapButton();
106:     if (state.soundOn) resumeAudio();
107:     if (state.tapTimes.length && now - state.tapTimes[state.tapTimes.length - 1] > 2200) {
108:       state.tapTimes = [];
109:       state.intervals = [];
110:     }
111:     if (state.tapTimes.length) {
112:       const interval = now - state.tapTimes[state.tapTimes.length - 1];
113:       if (interval >= 250 && interval <= 1500) {
114:         state.intervals.push(interval);
115:         state.intervals = state.intervals.slice(-6);
116:         const estimate = estimateBpm(state.intervals);
117:         if (estimate) {
118:           state.bpm = estimate;
119:           ui.bpm.textContent = String(estimate);
120:           ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
121:           setTempoReady(true);
122:           startClock();
123:         }
124:       } else if (interval > 1500) {
125:         state.intervals = [];
126:       }
127:     }
128:     state.tapTimes.push(now);
129:     state.tapTimes = state.tapTimes.slice(-7);
130:     if (!state.bpm) {
131:       ui.tempoCaption.textContent = state.tapTimes.length > 1 ? 'Seguí tocando para fijar el pulso' : 'Tocá al ritmo de tu base';
132:     }
133:     if (navigator.vibrate) navigator.vibrate(8);
134:   }
135: 
136:   function estimateBpm(intervals) {
137:     if (!intervals.length) return null;
138:     const ordered = [...intervals].sort((a, b) => a - b);
139:     const middle = Math.floor(ordered.length / 2);
140:     const median = ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
141:     const reliable = intervals.filter((value) => Math.abs(value - median) <= median * 0.18);
142:     const average = reliable.reduce((sum, value) => sum + value, 0) / reliable.length;
143:     return Math.max(40, Math.min(240, Math.round(60000 / average)));
144:   }
145: 
146:   function effectiveTempo() {
147:     return state.bpm ? state.bpm * (state.mode === 'doble' ? 2 : 1) : 0;
148:   }
149: 
150:   function setTempoReady(ready) {
151:     ui.tempoStatus.classList.toggle('running', ready && state.running);
152:     ui.tempoStatus.lastChild.textContent = ready ? (state.running ? 'EN MARCHA' : 'LISTO') : 'ESPERANDO';
153:   }
154: 
155:   function startClock() {
156:     if (!state.bpm || state.running) return;
157:     state.running = true;
158:     state.generation += 1;
159:     state.tickNumber = 0;
160:     state.nextTickAt = performance.now() + 70;
161:     setTempoReady(true);
162:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
163:     scheduleLoop(state.generation);
164:   }
165: 
166:   function scheduleLoop(generation) {
167:     if (!state.running || generation !== state.generation) return;
168:     const now = performance.now();
169:     const divisions = state.subdivision * (state.mode === 'doble' ? 2 : 1);
170:     const stepMs = 60000 / state.bpm / divisions;
171:     while (state.nextTickAt <= now + 100) {
172:       if (state.nextTickAt < now - stepMs) state.nextTickAt = now + 8;
173:       const scheduledAt = state.nextTickAt;
174:       const tick = state.tickNumber++;
175:       const beat = Math.floor(tick / divisions) % 4;
176:       const isAccent = tick % divisions === 0;
177:       queueTick(scheduledAt, beat, isAccent, generation);
178:       if (state.soundOn) scheduleClick(scheduledAt, isAccent);
179:       state.nextTickAt += stepMs;
180:     }
181:     state.timer = window.setTimeout(() => scheduleLoop(generation), 25);
182:   }
183: 
184:   function queueTick(time, beat, isAccent, generation) {
185:     const delay = Math.max(0, time - performance.now());
186:     const id = window.setTimeout(() => {
187:       state.tickTimerIds.delete(id);
188:       if (!state.running || generation !== state.generation) return;
189:       renderBeat(beat, isAccent);
190:       if (isAccent) onMainBeat(beat);
191:     }, delay);
192:     state.tickTimerIds.add(id);
193:   }
194: 
195:   function renderBeat(beat, isAccent) {
196:     ui.beatBoxes.forEach((box, index) => {
197:       box.classList.toggle('active', index === beat && isAccent);
198:       box.classList.toggle('sub-beat', index === beat && !isAccent);
199:     });
200:   }
201: 
202:   function onMainBeat(beat) {
203:     if (beat === 0) {
204:       state.roundNumber += 1;
205:       state.currentPrompt = choosePrompt(state.mode);
206:       state.rhymeRevealed = false;
207:       state.hitThisRound = false;
208:       ui.hit.disabled = true;
209:       ui.round.textContent = `RONDA ${String(state.roundNumber).padStart(2, '0')}`;
210:       ui.promptLabel.textContent = state.mode === 'esdrujulas' ? 'CONCEPTO · ACENTO EN LA ANTEPENÚLTIMA' : 'CONCEPTO · DOBLE TEMPO';
211:       ui.promptIndex.textContent = `#${String(state.roundNumber).padStart(2, '0')}`;
212:       ui.promptWord.textContent = state.currentPrompt.word;
213:       ui.promptWord.classList.remove('pop');
214:       void ui.promptWord.offsetWidth;
215:       ui.promptWord.classList.add('pop');
216:       ui.promptHint.textContent = state.currentPrompt.hint;
217:       ui.instruction.textContent = state.mode === 'doble' ? 'Doblá las sílabas; el remate llega en el pulso 3.' : 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
218:       showEmptyRhymes();
219:     }
220:     if (beat === 2 && state.currentPrompt && !state.rhymeRevealed) revealRhymes();
221:   }
