263:   function confirmHit() {
264:     if (!state.rhymeRevealed || state.hitThisRound) return;
265:     state.hitThisRound = true;
266:     state.streak += 1;
267:     state.hits += 1;
268:     state.best = Math.max(state.best, state.streak);
269:     updateStats();
270:     saveProgress();
271:     ui.hit.disabled = true;
272:     ui.hit.innerHTML = 'REMATE GUARDADO <span>✓</span>';
273:     window.setTimeout(() => { ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>'; }, 1100);
274:     showToast('Una más para la racha. ¡Buen remate!');
275:   }
276: 
277:   function updateStats() {
278:     ui.streak.textContent = String(state.streak);
279:     ui.hits.textContent = String(state.hits);
280:     ui.best.textContent = String(state.best);
281:   }
